import{p as o,b as e,C as l}from"./vue-vendor-de6b2611.js";const s={class:"markdown-body"},c=l(`<h1>升级更新</h1><h2>BIOS更新</h2><blockquote><p>刷写BIOS属于非常规升级，操作失误，易造成死机、不开机等异常情况，需返厂维修，造成的一切损失和费用，由客户自行承担。一经执行BIOS操作，默认接受并认可以上条款。</p></blockquote><ol><li><p>准备工作：</p><ul><li><p>准备一个U盘，并格式化为 <code>FAT32</code>格式（使用<a href="https://www.diskgenius.cn/"><code>Diskgenius</code></a>软件）；</p></li><li><p>BIOS文件：</p></li></ul></li></ol><table><thead><tr><th>产品型号</th><th>R1/R1Pro</th><th>R2/R2 NUC</th><th>R2 Max</th></tr></thead><tbody><tr><td>下载链接</td><td><a href="https://dl.ikoolcore.com">官方网盘</a></td><td><a href="https://dl.ikoolcore.com">官方网盘</a></td><td><a href="https://dl.ikoolcore.com">官方网盘</a></td></tr></tbody></table><pre><code>    &gt; 风险提示⚠️：由于 R1、R2是板载内存设计，请注意其不同内存大小的BIOS文件不同，刷错版本将导致不开机。
</code></pre><ol start="2"><li><p>将解压后的<code>EFI</code>文件夹完整地复制到U盘的<strong>根目录</strong>下； <img src="https://s2.loli.net/2023/10/30/mdF6ePGTCq5z7ML.png" alt="image.png"></p></li><li><p>拆掉所有外接存储设备（包括硬盘、优盘、外接硬盘等），插入U盘，接好显示器，通电之后，设备将会自动执行刷写BIOS的程序；**（一定需要拆除硬盘后再插优盘通电，才会实现自动刷写新的BIOS文件，否则自动刷写程序识别的磁盘序号会错误，无法自动刷写BIOS）**4. 刷写过程中，屏幕将会自动跑代码，待出现<code>FPT Operation Successful</code>界面后，即表示刷写成功。 <img src="https://s2.loli.net/2023/10/30/1moD6yeQxKXsiJE.png" alt="image.png"></p></li><li><p>注意事项：</p><ol><li>刷写过程中<strong>不要有任何操作，不能断电</strong>，出现<code>FPT Operation Successful</code>界面后，就说明刷写程序成功了，然后拔出 U 盘，把机器<strong>断电</strong>重启，首次重启较慢，请耐心等待即可。</li><li>刷写BIOS后的首次启动较慢，请耐心等待。</li><li>刷 BIOS 有风险，谨慎操作，刷崩了得售后返厂。</li></ol></li></ol>`,7),i=[c],h={__name:"update",setup(r,{expose:t}){return t({frontmatter:{}}),(a,p)=>(o(),e("div",s,i))}};export{h as default};
